import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { RUNTIME_COMMAND_ENVELOPE_VERSION } from "@moe/contracts";
import { SqliteEventStore } from "@moe/store";
import { expect, it } from "vitest";

import { createStoreDependencies } from "./daemon-store-dependencies.js";
import { handleCommandRequest } from "./http/http-adapter.js";
import { WIRE_PROTOCOL_VERSION } from "./http/http-contract.js";

const CREDENTIAL = "product-contract-probe-credential";
const PROJECT = "proj-product-contract-probe";
const KIND = "product_contract.approve_gate_1" as const;

function durableCounts(storePath: string): Readonly<{ decisions: number; events: number }> {
  const store = SqliteEventStore.openForProject(storePath, PROJECT);
  try {
    return Object.freeze({
      decisions: store.readCommandDecisionsAfter(0n, 1_000).items.length,
      events: store.readEventsAfter(0n, 1_000).items.length,
    });
  } finally {
    store.close();
  }
}

it("refuses the published but unwired product contract command without durable writes", () => {
  const directory = mkdtempSync(join(tmpdir(), "moe-product-contract-probe-"));
  const storePath = join(directory, "store.db");
  const provider = createStoreDependencies({
    clock: () => "2026-08-27T16:00:00.000Z",
    credential: CREDENTIAL,
    principalId: "operator-local",
    projectId: PROJECT,
    storePath,
  });

  try {
    const before = durableCounts(storePath);
    const response = handleCommandRequest(provider.provide(), {
      body: new TextEncoder().encode(JSON.stringify({
        commandId: "cmd-product-contract-probe",
        commandKind: KIND,
        correlationId: "corr-product-contract-probe",
        expectedVersion: 0,
        payload: {},
        requestDigest: "a".repeat(64),
        schemaVersion: RUNTIME_COMMAND_ENVELOPE_VERSION,
        sessionCredential: CREDENTIAL,
        targetAggregateId: "product-contract-probe",
      })),
      credential: CREDENTIAL,
      protocolVersion: WIRE_PROTOCOL_VERSION,
    });
    const after = durableCounts(storePath);

    expect(response).toMatchObject({
      error: { code: "INPUT_INVALID" },
      httpStatus: 400,
      ok: false,
      outcome: "REFUSED",
      stage: "REGISTRY",
    });
    expect(after.decisions - before.decisions).toBe(0);
    expect(after.events - before.events).toBe(0);
    expect(after).toEqual(before);
  } finally {
    provider.close();
    rmSync(directory, { force: true, recursive: true });
  }
});
```

The probe drives the shipped handleCommandRequest over createStoreDependencies and a real SqliteEventStore. It pins the exact refusal code/layering seam (INPUT_INVALID / REGISTRY) and proves the command appended zero decisions and zero events relative to the initialized store. The daemon does not accept the new kind; sibling writer task-7997ba7cefe542698d5a8078dbe56283 remains the consumer that will wire it.
